PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3.org/ns/leap/Refractarius/ref#>
SELECT ?zone ?label ?tsid ?point ?pclass
WHERE {
  ?zone a brick:Zone_F2_Z01 .
}

SELECT ?point ?label ?tsid WHERE {
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point rdfs:label ?label . }
  FILTER(CONTAINS(str(?point), "Zone_F2"))
}

